scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 210) @Event210;
	If ($Event == 240) @Event240;
	
	Return;
	
@Event210:
	If ($firstdie == 0) @firstdie0;
	If ($firstdie == 1) @firstdie1;
@firstdie0:
	Say("独孤剑：我们赶了这么多天的路，你累不累？不如……我们歇会儿再上山？", 1);
	Say("张琳心：我不累，真的，我知道你心里着急血书，我也急着想见到爹，我们快上山吧！", 21);
	Return;
@firstdie1:
	Say("张琳心：怎么会死了这么多人？真是太可怕了！", 25);
	Return;	
	
	
@Event240:
	Say("张琳心：难道真如那些杀手所说，一代大侠方勉竟是五色教中人？", 24);
	Say("独孤剑：但柳前辈说这决不可能，我师父生前对方勉也是敬慕得很，两位前辈不可能都看错人吧？。", 1);
	Say("张琳心：这到底是怎么回事？", 24);
	Say("独孤剑：你哥哥曾经对方勉颇有微词，看来这中间定有内情……", 1); 
	Return;

traps.Trap01.txt:
// 切换到林间小道

	If ($Event == 30) @Event30; 
	If ($Event == 210) @Event30;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map005_林间小道.map");
	LoadNpc("map005.npc");
	LoadObj("map005.obj");
	SetPlayerPos(14, 49);
	SetPlayerDir(3);
	FadeIn();
	Return;	

@Event30:
	Say("独孤剑：赶紧上山吧！", 9);
	Return;

traps.Trap02.txt:
// 切换到九猴洞

	If ($Event == 30) @Event30; 
	If ($Event == 210) @Event210;			//主角等级与敌人等级差别太大时，没必要再练级了
	// zroc add
	If ($Event >> 210) @GEvent210;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("战斗.mp3");
	LoadMap("map007_武夷山九猴洞.map");
	LoadNpc("map007.npc");
	SaveNpc("temp_map007.npc");  //有反复战斗
	LoadObj("map007.obj");
	SetPlayerPos(3, 80);
	SetPlayerDir(4);
	SetNpcScript("张琳心", "");
	FadeIn();
	Return;	

@Event30:
	If ($Say == 1) @Say; 
	Say("独孤剑：这洞黑漆漆的，里面不知有什么古怪。", 1);
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("战斗.mp3");
	LoadMap("map007_武夷山九猴洞.map");  
	LoadNpc("map007.npc");
	SaveNpc("temp_map007.npc");  //有反复战斗
	LoadObj("map007.obj");
	SetPlayerPos(3, 80);
	SetPlayerDir(4);
	Assign($Say, 1);
	FadeIn();
	Return;	
@Say:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("战斗.mp3");
	LoadMap("map007_武夷山九猴洞.map");  
	LoadNpc("map007.npc");
	SaveNpc("temp_map007.npc");  //有反复战斗
	LoadObj("map007.obj");
	SetPlayerPos(3, 80);
	SetPlayerDir(4);
	FadeIn();
	Return;	
		
	
	
@Event210:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map007_武夷山九猴洞.map");
	LoadNpc("map007_escape.npc");
	LoadObj("map007_event210.obj");
	SetPlayerPos(3, 80);
	SetPlayerDir(4);
	SetNpcScript("张琳心", "张琳心对话.txt");
	FadeIn();
	Return;

@GEvent210:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("战斗.mp3");
	LoadMap("map007_武夷山九猴洞.map");
	LoadNpc("map007_escape.npc");
	LoadObj("map007.obj");
	SetPlayerPos(3, 80);
	SetPlayerDir(4);
	SetNpcScript("张琳心", "张琳心对话.txt");
	FadeIn();
	Return;

traps.Trap03.txt:
// 在武夷山下发现武夷派弟子尸体

	If ($Event == 210) @Event210;	
	Return;
	
@Event210:
	StopMusic();
	PlayMusic("追缘.mp3");
	PlayerRunTo(14, 35);
	Say("独孤剑：哎呀！不好！我们还是来迟了一步！", 6);
	Say("张琳心：啊？！怎么会死了这么多人？", 25);
	Assign($firstdie, 1);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	SetMapTrap(3, "");
	Return;
